Subject: [PATCH] smokeview source: fix error in smoke loading introduced in
 672861f2 9/5/2018

---
 Source/smokeview/IOsmoke.c | 8 +++++---
 1 file changed, 5 insertions(+), 3 deletions(-)

diff --git a/Source/smokeview/IOsmoke.c b/Source/smokeview/IOsmoke.c
index b9b448b4b..b6d8bd266 100644
--- a/Source/smokeview/IOsmoke.c
+++ b/Source/smokeview/IOsmoke.c
@@ -5941,10 +5941,12 @@ FILE_SIZE ReadSmoke3D(int iframe,int ifile,int flag, int *errorcode){
       PRINTF(" - skipped (max soot opacity<%0.f)\n", load_3dsmoke_cutoff);
       return_flag = 1;
     }
-    if(smoke3di->finalize==1){
-      SmokeWrapup(smoke3di);
+    if(return_flag==1){
+      if(smoke3di->finalize==1){
+        SmokeWrapup(smoke3di);
+      }
+      return 0;
     }
-    if(return_flag==1)return 0;
   }
   CheckMemory;
   if(
